-- Frozen shipment cost, immutable arrivals/returns/losses. In-transit stock is not a sellable warehouse balance.
CREATE TABLE inventory.transit_transfers(
 id uuid PRIMARY KEY,company_id uuid NOT NULL REFERENCES core.companies(id),source_id uuid NOT NULL,destination_id uuid NOT NULL,reference text NOT NULL,reason text NOT NULL,inventory_account_id uuid,transit_account_id uuid,journal_entry_id uuid,
 created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL REFERENCES identity.users(id),UNIQUE(company_id,id),FOREIGN KEY(company_id,id) REFERENCES platform.documents(company_id,id),FOREIGN KEY(company_id,source_id) REFERENCES catalog.warehouses(company_id,id),FOREIGN KEY(company_id,destination_id) REFERENCES catalog.warehouses(company_id,id),FOREIGN KEY(company_id,inventory_account_id) REFERENCES accounting.accounts(company_id,id),FOREIGN KEY(company_id,transit_account_id) REFERENCES accounting.accounts(company_id,id),FOREIGN KEY(company_id,journal_entry_id) REFERENCES accounting.journal_entries(company_id,id),CHECK(source_id<>destination_id)
);
CREATE UNIQUE INDEX transit_dispatch_reference ON inventory.transit_transfers(company_id,lower(btrim(reference)));
CREATE TABLE inventory.transit_transfer_lines(
 id uuid PRIMARY KEY,company_id uuid NOT NULL REFERENCES core.companies(id),transfer_id uuid NOT NULL,product_id uuid NOT NULL,quantity numeric(20,6) NOT NULL CHECK(quantity>0),cost numeric(20,2) NOT NULL CHECK(cost>=0),stock_balance_id uuid NOT NULL,
 quantity_before numeric(20,6) NOT NULL,quantity_after numeric(20,6) NOT NULL,value_before numeric(20,2) NOT NULL,value_after numeric(20,2) NOT NULL,reserved_after numeric(20,6) NOT NULL,revision_before bigint NOT NULL,revision_after bigint NOT NULL,snapshot jsonb NOT NULL,
 UNIQUE(company_id,id),UNIQUE(company_id,transfer_id,product_id),FOREIGN KEY(company_id,id,transfer_id) REFERENCES platform.document_lines(company_id,id,document_id),FOREIGN KEY(company_id,transfer_id) REFERENCES inventory.transit_transfers(company_id,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(company_id,product_id) REFERENCES catalog.products(company_id,id),FOREIGN KEY(company_id,stock_balance_id) REFERENCES inventory.stock_balances(company_id,id),CHECK(quantity_after=quantity_before-quantity AND value_after=value_before-cost AND reserved_after BETWEEN 0 AND quantity_after AND value_after>=0 AND revision_before>0 AND revision_after>revision_before)
);
CREATE TABLE inventory.transit_events(
 id uuid PRIMARY KEY,company_id uuid NOT NULL REFERENCES core.companies(id),transfer_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN('RECEIPT','RETURN','SHORTAGE')),warehouse_id uuid,reference text NOT NULL,reason text NOT NULL,debit_account_id uuid,journal_entry_id uuid,
 created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL REFERENCES identity.users(id),UNIQUE(company_id,id),FOREIGN KEY(company_id,id) REFERENCES platform.documents(company_id,id),FOREIGN KEY(company_id,transfer_id) REFERENCES inventory.transit_transfers(company_id,id),FOREIGN KEY(company_id,warehouse_id) REFERENCES catalog.warehouses(company_id,id),FOREIGN KEY(company_id,debit_account_id) REFERENCES accounting.accounts(company_id,id),FOREIGN KEY(company_id,journal_entry_id) REFERENCES accounting.journal_entries(company_id,id),CHECK((kind='SHORTAGE')=(warehouse_id IS NULL))
);
CREATE UNIQUE INDEX transit_event_reference ON inventory.transit_events(company_id,transfer_id,kind,lower(btrim(reference)));
CREATE TABLE inventory.transit_event_lines(
 id uuid PRIMARY KEY,company_id uuid NOT NULL REFERENCES core.companies(id),event_id uuid NOT NULL,transfer_line_id uuid NOT NULL,quantity numeric(20,6) NOT NULL CHECK(quantity>0),cost numeric(20,2) NOT NULL CHECK(cost>=0),stock_balance_id uuid,
 quantity_before numeric(20,6),quantity_after numeric(20,6),value_before numeric(20,2),value_after numeric(20,2),reserved_after numeric(20,6),revision_before bigint,revision_after bigint,
 UNIQUE(company_id,id),UNIQUE(company_id,event_id,transfer_line_id),FOREIGN KEY(company_id,id,event_id) REFERENCES platform.document_lines(company_id,id,document_id),FOREIGN KEY(company_id,event_id) REFERENCES inventory.transit_events(company_id,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(company_id,transfer_line_id) REFERENCES inventory.transit_transfer_lines(company_id,id),FOREIGN KEY(company_id,stock_balance_id) REFERENCES inventory.stock_balances(company_id,id),
 CHECK(num_nonnulls(stock_balance_id,quantity_before,quantity_after,value_before,value_after,reserved_after,revision_before,revision_after) IN(0,8)),CHECK(stock_balance_id IS NULL OR(quantity_after=quantity_before+quantity AND value_after=value_before+cost AND reserved_after BETWEEN 0 AND quantity_after AND value_after>=0 AND revision_before>0 AND revision_after>revision_before))
);
DO $$ DECLARE tb text;BEGIN FOREACH tb IN ARRAY ARRAY['transit_transfers','transit_transfer_lines','transit_events','transit_event_lines'] LOOP
 EXECUTE format('ALTER TABLE inventory.%I ENABLE ROW LEVEL SECURITY',tb);EXECUTE format('ALTER TABLE inventory.%I FORCE ROW LEVEL SECURITY',tb);EXECUTE format('CREATE POLICY company_scope ON inventory.%I USING(company_id=core.current_company()) WITH CHECK(company_id=core.current_company())',tb);EXECUTE format('CREATE INDEX ON inventory.%I(company_id)',tb);EXECUTE format('CREATE TRIGGER append_only BEFORE UPDATE OR DELETE ON inventory.%I FOR EACH ROW EXECUTE FUNCTION platform.reject_mutation()',tb);END LOOP;END $$;
CREATE INDEX ON inventory.transit_transfers(company_id,source_id);CREATE INDEX ON inventory.transit_transfers(company_id,destination_id);CREATE INDEX ON inventory.transit_transfer_lines(company_id,transfer_id);CREATE INDEX ON inventory.transit_events(company_id,transfer_id,kind);CREATE INDEX ON inventory.transit_event_lines(company_id,transfer_line_id);
CREATE VIEW inventory.transit_line_balances WITH(security_invoker=true) AS
 SELECT tl.*,coalesce(e.received_quantity,0) AS received_quantity,coalesce(e.returned_quantity,0) AS returned_quantity,coalesce(e.shortage_quantity,0) AS shortage_quantity,coalesce(e.received_cost,0) AS received_cost,coalesce(e.returned_cost,0) AS returned_cost,coalesce(e.shortage_cost,0) AS shortage_cost,tl.quantity-coalesce(e.quantity,0) AS remaining_quantity,tl.cost-coalesce(e.cost,0) AS remaining_cost
 FROM inventory.transit_transfer_lines tl LEFT JOIN LATERAL(SELECT sum(el.quantity) AS quantity,sum(el.cost) AS cost,sum(el.quantity) FILTER(WHERE h.kind='RECEIPT') AS received_quantity,sum(el.quantity) FILTER(WHERE h.kind='RETURN') AS returned_quantity,sum(el.quantity) FILTER(WHERE h.kind='SHORTAGE') AS shortage_quantity,sum(el.cost) FILTER(WHERE h.kind='RECEIPT') AS received_cost,sum(el.cost) FILTER(WHERE h.kind='RETURN') AS returned_cost,sum(el.cost) FILTER(WHERE h.kind='SHORTAGE') AS shortage_cost FROM inventory.transit_event_lines el JOIN inventory.transit_events h ON h.company_id=el.company_id AND h.id=el.event_id WHERE el.company_id=tl.company_id AND el.transfer_line_id=tl.id)e ON true;
CREATE VIEW inventory.transit_transfer_balances WITH(security_invoker=true) AS
 SELECT t.*,CASE WHEN m.open_lines=0 THEN 'CLOSED' WHEN m.processed_lines=0 THEN 'IN_TRANSIT' ELSE 'PARTIAL' END AS state,m.open_lines AS remaining_line_count,m.cost AS shipped_cost,m.received_cost,m.returned_cost,m.shortage_cost,m.remaining_cost
 FROM inventory.transit_transfers t JOIN LATERAL(SELECT count(*) FILTER(WHERE remaining_quantity>0) AS open_lines,count(*) FILTER(WHERE remaining_quantity<quantity) AS processed_lines,sum(cost) AS cost,sum(received_cost) AS received_cost,sum(returned_cost) AS returned_cost,sum(shortage_cost) AS shortage_cost,sum(remaining_cost) AS remaining_cost FROM inventory.transit_line_balances WHERE company_id=t.company_id AND transfer_id=t.id)m ON true;
INSERT INTO identity.permissions(code,description) VALUES('inventory.transit.read','Read shipment tracking in assigned source or destination'),('inventory.transit.dispatch','Dispatch unreserved source stock into transit'),('inventory.transit.receive','Receive actual arrivals in assigned destination'),('inventory.transit.return','Receive undelivered stock back at source'),('inventory.transit.resolve','Approve evidenced in-transit shortage losses');
CREATE FUNCTION identity.seed_transit_roles(c uuid) RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN
 INSERT INTO identity.role_permissions(company_id,role_id,permission_code) SELECT c,r.id,p.code FROM identity.roles r CROSS JOIN identity.permissions p WHERE r.company_id=c AND ((r.code='ADMIN' AND p.code LIKE 'inventory.transit.%') OR(r.code='WAREHOUSE' AND p.code IN('inventory.transit.read','inventory.transit.dispatch','inventory.transit.receive','inventory.transit.return')) OR(r.code='FINANCE' AND p.code='inventory.transit.resolve')) ON CONFLICT DO NOTHING;
 INSERT INTO accounting.accounts(company_id,code,name,kind,control_kind) VALUES(c,'1250','Inventory in transit','ASSET','INVENTORY'),(c,'5500','Interwarehouse transit losses','EXPENSE',NULL) ON CONFLICT(company_id,code) DO NOTHING;
 INSERT INTO accounting.account_mappings(company_id,purpose,account_id) SELECT c,v.purpose,a.id FROM(VALUES('INVENTORY_TRANSIT','1250'),('TRANSIT_LOSS','5500'))v(purpose,code) JOIN accounting.accounts a ON a.company_id=c AND a.code=v.code ON CONFLICT DO NOTHING;
 INSERT INTO platform.document_sequences(company_id,document_type,prefix) VALUES(c,'TRANSIT_DISPATCH','TT-'),(c,'TRANSIT_RECEIPT','TIR-'),(c,'TRANSIT_ADJUSTMENT','TIA-') ON CONFLICT DO NOTHING;
END $$;
DO $$ DECLARE c uuid;BEGIN FOR c IN SELECT id FROM core.companies LOOP PERFORM set_config('htt.company_id',c::text,true);PERFORM identity.seed_transit_roles(c);END LOOP;PERFORM set_config('htt.company_id','',true);END $$;
CREATE FUNCTION inventory.transit_number(p text) RETURNS text LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE n bigint;prefix text;BEGIN
 IF p NOT IN('TRANSIT_DISPATCH','TRANSIT_RECEIPT','TRANSIT_ADJUSTMENT') THEN RAISE EXCEPTION 'Invalid transit sequence' USING ERRCODE='HI422';END IF;
 UPDATE platform.document_sequences s SET next_value=next_value+1 WHERE company_id=core.current_company() AND document_type=p RETURNING next_value-1,s.prefix INTO n,prefix;
 IF NOT FOUND THEN RAISE EXCEPTION 'Transit sequence missing' USING ERRCODE='HI422';END IF;RETURN prefix||lpad(n::text,greatest(6,length(n::text)),'0');END $$;
CREATE FUNCTION inventory.transit_delta(w uuid,p uuid,qty numeric,val numeric) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE c uuid:=core.current_company();b inventory.stock_balances;v inventory.stock_values;rev bigint;BEGIN
 SELECT * INTO b FROM inventory.stock_balances WHERE company_id=c AND warehouse_id=w AND product_id=p;SELECT * INTO v FROM inventory.stock_values WHERE company_id=c AND stock_balance_id=b.id;
 IF NOT FOUND OR b.on_hand+qty<b.reserved OR v.value+val<0 THEN RAISE EXCEPTION 'Insufficient unreserved valued stock' USING ERRCODE='HI409';END IF;
 UPDATE inventory.stock_balances SET on_hand=on_hand+qty WHERE company_id=c AND id=b.id;UPDATE inventory.stock_values SET value=value+val WHERE company_id=c AND id=v.id;SELECT revision INTO rev FROM inventory.stock_balances WHERE company_id=c AND id=b.id;
 RETURN jsonb_build_object('id',b.id,'quantityBefore',b.on_hand,'quantityAfter',b.on_hand+qty,'valueBefore',v.value,'valueAfter',v.value+val,'reservedAfter',b.reserved,'revisionBefore',b.revision,'revisionAfter',rev);
END $$;
CREATE FUNCTION inventory.dispatch_transit(p_source uuid,p_destination uuid,p_reference text,p_reason text,items jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE c uuid:=core.current_company();a uuid:=core.current_actor();tid uuid:=gen_random_uuid();today date;w uuid;products uuid[];entry jsonb;p uuid;qty numeric;cost numeric;total numeric:=0;b inventory.stock_balances;v inventory.stock_values;movement jsonb;lid uuid;no int:=0;inv uuid;transit uuid;j uuid;BEGIN
 PERFORM inventory.require_access('inventory.transit.dispatch',p_source);today:=inventory.control_today();
 IF p_source IS NULL OR p_destination IS NULL OR p_source=p_destination THEN RAISE EXCEPTION 'Distinct source and destination required' USING ERRCODE='HI422';END IF;
 FOR w IN SELECT unnest(ARRAY[p_source,p_destination]) ORDER BY 1 LOOP PERFORM inventory.control_warehouse(w);END LOOP;
 IF p_reference IS NULL OR length(btrim(p_reference)) NOT BETWEEN 1 AND 200 OR p_reason IS NULL OR length(btrim(p_reason)) NOT BETWEEN 1 AND 2000 OR items IS NULL OR jsonb_typeof(items)<>'array' OR jsonb_array_length(items) NOT BETWEEN 1 AND 50 OR EXISTS(SELECT 1 FROM jsonb_array_elements(items)x GROUP BY x->>'productId' HAVING count(*)>1) OR EXISTS(SELECT 1 FROM jsonb_array_elements(items)x WHERE x->>'productId' IS NULL OR x->>'quantity' IS NULL OR (x->>'quantity')::numeric<=0 OR (x->>'quantity')::numeric<>round((x->>'quantity')::numeric,6) OR (x->>'quantity')::numeric>99999999999999.999999) THEN RAISE EXCEPTION 'Reference, reason and distinct positive base quantities required' USING ERRCODE='HI422';END IF;
 SELECT array_agg((x->>'productId')::uuid ORDER BY x->>'productId') INTO products FROM jsonb_array_elements(items)x;
 INSERT INTO platform.documents(id,company_id,document_type,number,business_date,state,created_by) VALUES(tid,c,'TRANSIT_DISPATCH',inventory.transit_number('TRANSIT_DISPATCH'),today,'CONFIRMED',a);
 PERFORM inventory.lock_control_balances(ARRAY[p_source],products,tid);
 FOR entry IN SELECT * FROM jsonb_array_elements(items) ORDER BY value->>'productId' LOOP
 p:=(entry->>'productId')::uuid;qty:=(entry->>'quantity')::numeric;SELECT * INTO b FROM inventory.stock_balances WHERE company_id=c AND warehouse_id=p_source AND product_id=p;SELECT * INTO v FROM inventory.stock_values WHERE company_id=c AND stock_balance_id=b.id;
 IF b.on_hand-b.reserved<qty THEN RAISE EXCEPTION 'Dispatch exceeds unreserved source stock' USING ERRCODE='HI409';END IF;
 cost:=CASE WHEN qty=b.on_hand THEN v.value ELSE round(v.value*qty/b.on_hand,2) END;movement:=inventory.transit_delta(p_source,p,-qty,-cost);no:=no+1;lid:=gen_random_uuid();
 INSERT INTO platform.document_lines(id,company_id,document_id,line_no,created_by) VALUES(lid,c,tid,no,a);
 INSERT INTO inventory.transit_transfer_lines(id,company_id,transfer_id,product_id,quantity,cost,stock_balance_id,quantity_before,quantity_after,value_before,value_after,reserved_after,revision_before,revision_after,snapshot) VALUES(lid,c,tid,p,qty,cost,(movement->>'id')::uuid,(movement->>'quantityBefore')::numeric,(movement->>'quantityAfter')::numeric,(movement->>'valueBefore')::numeric,(movement->>'valueAfter')::numeric,(movement->>'reservedAfter')::numeric,(movement->>'revisionBefore')::bigint,(movement->>'revisionAfter')::bigint,inventory.control_product(p));total:=total+cost;
 END LOOP;
 IF total>0 THEN inv:=accounting.settlement_account('INVENTORY','ASSET','INVENTORY');transit:=accounting.settlement_account('INVENTORY_TRANSIT','ASSET','INVENTORY');IF transit=inv THEN RAISE EXCEPTION 'Transit account must differ from warehouse inventory' USING ERRCODE='HI422';END IF;
 j:=accounting.post_journal(tid,1,'TRANSIT_DISPATCH',today,'Dispatch inventory into transit',jsonb_build_array(jsonb_build_object('accountId',transit,'debit',total),jsonb_build_object('accountId',inv,'credit',total)));END IF;
 INSERT INTO inventory.transit_transfers(id,company_id,source_id,destination_id,reference,reason,inventory_account_id,transit_account_id,journal_entry_id,created_by) VALUES(tid,c,p_source,p_destination,btrim(p_reference),btrim(p_reason),inv,transit,j,a);
 UPDATE platform.documents SET state='POSTED' WHERE company_id=c AND id=tid;RETURN tid;
END $$;
CREATE FUNCTION inventory.post_transit_event(p_transfer uuid,p_kind text,p_reference text,p_reason text,items jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE c uuid:=core.current_company();a uuid:=core.current_actor();eid uuid:=gen_random_uuid();ship inventory.transit_transfers;today date;warehouse uuid;dtype text;entry jsonb;line inventory.transit_transfer_lines;products uuid[];qty numeric;cost numeric;used_q numeric;used_cost numeric;total numeric:=0;movement jsonb;lid uuid;no int:=0;debit_account uuid;j uuid;
BEGIN
 SELECT * INTO ship FROM inventory.transit_transfers WHERE company_id=c AND id=p_transfer;IF NOT FOUND THEN RAISE EXCEPTION 'Transit transfer unavailable' USING ERRCODE='HT404';END IF;
 IF p_kind='RECEIPT' THEN warehouse:=ship.destination_id;PERFORM inventory.require_access('inventory.transit.receive',warehouse);dtype:='TRANSIT_RECEIPT';
 ELSIF p_kind='RETURN' THEN warehouse:=ship.source_id;PERFORM inventory.require_access('inventory.transit.return',warehouse);dtype:='TRANSIT_ADJUSTMENT';
 ELSIF p_kind='SHORTAGE' THEN PERFORM inventory.require_control_permission('inventory.transit.resolve');dtype:='TRANSIT_ADJUSTMENT';ELSE RAISE EXCEPTION 'Invalid transit disposition' USING ERRCODE='HI422';END IF;
 today:=inventory.control_today();SELECT * INTO ship FROM inventory.transit_transfers WHERE company_id=c AND id=p_transfer FOR UPDATE;
 IF warehouse IS NOT NULL THEN PERFORM inventory.control_warehouse(warehouse);END IF;
 IF p_reference IS NULL OR length(btrim(p_reference)) NOT BETWEEN 1 AND 200 OR p_reason IS NULL OR length(btrim(p_reason)) NOT BETWEEN 1 AND 2000 OR items IS NULL OR jsonb_typeof(items)<>'array' OR jsonb_array_length(items) NOT BETWEEN 1 AND 50 OR EXISTS(SELECT 1 FROM jsonb_array_elements(items)x GROUP BY x->>'transferLineId' HAVING count(*)>1) OR EXISTS(SELECT 1 FROM jsonb_array_elements(items)x WHERE x->>'transferLineId' IS NULL OR x->>'quantity' IS NULL OR (x->>'quantity')::numeric<=0 OR (x->>'quantity')::numeric<>round((x->>'quantity')::numeric,6) OR (x->>'quantity')::numeric>99999999999999.999999) THEN RAISE EXCEPTION 'Reference, reason and distinct positive transit quantities required' USING ERRCODE='HI422';END IF;
 -- Validate every source before creating any warehouse balance; no silent missing IDs.
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(items)x WHERE NOT EXISTS(SELECT 1 FROM inventory.transit_transfer_lines tl WHERE tl.company_id=c AND tl.transfer_id=p_transfer AND tl.id=(x->>'transferLineId')::uuid)) THEN RAISE EXCEPTION 'Transit line unavailable for this shipment' USING ERRCODE='HT404';END IF;
 INSERT INTO platform.documents(id,company_id,document_type,number,business_date,state,created_by) VALUES(eid,c,dtype,inventory.transit_number(dtype),today,'CONFIRMED',a);
 IF warehouse IS NOT NULL THEN SELECT array_agg(tl.product_id ORDER BY tl.product_id) INTO products FROM inventory.transit_transfer_lines tl JOIN jsonb_array_elements(items)x ON tl.id=(x->>'transferLineId')::uuid WHERE tl.company_id=c AND tl.transfer_id=p_transfer;PERFORM inventory.lock_control_balances(ARRAY[warehouse],products,eid);END IF;
 FOR entry IN SELECT x.value FROM jsonb_array_elements(items)x JOIN inventory.transit_transfer_lines tl ON tl.company_id=c AND tl.id=(x.value->>'transferLineId')::uuid ORDER BY tl.product_id LOOP
 SELECT * INTO line FROM inventory.transit_transfer_lines WHERE company_id=c AND id=(entry->>'transferLineId')::uuid;
 SELECT coalesce(sum(el.quantity),0),coalesce(sum(el.cost),0) INTO used_q,used_cost FROM inventory.transit_event_lines el WHERE el.company_id=c AND el.transfer_line_id=line.id;
 qty:=(entry->>'quantity')::numeric;IF used_q+qty>line.quantity THEN RAISE EXCEPTION 'Quantity exceeds remaining in-transit balance' USING ERRCODE='HI409';END IF;
 cost:=round(line.cost*(used_q+qty)/line.quantity,2)-used_cost;movement:='{}'::jsonb;
 IF warehouse IS NOT NULL THEN movement:=inventory.transit_delta(warehouse,line.product_id,qty,cost);END IF;
 no:=no+1;lid:=gen_random_uuid();INSERT INTO platform.document_lines(id,company_id,document_id,line_no,created_by) VALUES(lid,c,eid,no,a);
 INSERT INTO inventory.transit_event_lines(id,company_id,event_id,transfer_line_id,quantity,cost,stock_balance_id,quantity_before,quantity_after,value_before,value_after,reserved_after,revision_before,revision_after) VALUES(lid,c,eid,line.id,qty,cost,(movement->>'id')::uuid,(movement->>'quantityBefore')::numeric,(movement->>'quantityAfter')::numeric,(movement->>'valueBefore')::numeric,(movement->>'valueAfter')::numeric,(movement->>'reservedAfter')::numeric,(movement->>'revisionBefore')::bigint,(movement->>'revisionAfter')::bigint);total:=total+cost;
 END LOOP;
 IF total>0 THEN
 PERFORM 1 FROM accounting.accounts WHERE company_id=c AND id=ship.transit_account_id AND active AND kind='ASSET' AND control_kind='INVENTORY' FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'Original transit control account inactive' USING ERRCODE='HI422';END IF;
 IF p_kind='SHORTAGE' THEN debit_account:=accounting.settlement_account('TRANSIT_LOSS','EXPENSE');ELSE debit_account:=ship.inventory_account_id;PERFORM 1 FROM accounting.accounts WHERE company_id=c AND id=debit_account AND active AND kind='ASSET' AND control_kind='INVENTORY' FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'Original inventory control account inactive' USING ERRCODE='HI422';END IF;END IF;
 j:=accounting.post_journal(eid,1,'TRANSIT_'||p_kind,today,'Transit '||lower(p_kind)||' at frozen shipment cost',jsonb_build_array(jsonb_build_object('accountId',debit_account,'debit',total),jsonb_build_object('accountId',ship.transit_account_id,'credit',total)));END IF;
 INSERT INTO inventory.transit_events(id,company_id,transfer_id,kind,warehouse_id,reference,reason,debit_account_id,journal_entry_id,created_by) VALUES(eid,c,p_transfer,p_kind,warehouse,btrim(p_reference),btrim(p_reason),debit_account,j,a);
 UPDATE platform.documents SET state='POSTED' WHERE company_id=c AND id=eid;RETURN eid;
END $$;
CREATE FUNCTION inventory.guard_transit_document() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF OLD.state='POSTED' AND OLD.document_type IN('TRANSIT_DISPATCH','TRANSIT_RECEIPT','TRANSIT_ADJUSTMENT') THEN RAISE EXCEPTION 'Posted transit document is immutable' USING ERRCODE='23514';END IF;RETURN NEW;END $$;
CREATE TRIGGER transit_document BEFORE UPDATE ON platform.documents FOR EACH ROW EXECUTE FUNCTION inventory.guard_transit_document();
CREATE FUNCTION inventory.validate_transit() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE c uuid:=NEW.company_id;tid uuid;eid uuid;ship inventory.transit_transfers;ev inventory.transit_events;total numeric;BEGIN
 IF TG_TABLE_NAME='transit_transfers' THEN tid:=NEW.id;ELSIF TG_TABLE_NAME='transit_transfer_lines' THEN tid:=NEW.transfer_id;ELSIF TG_TABLE_NAME='transit_events' THEN tid:=NEW.transfer_id;eid:=NEW.id;ELSE SELECT h.transfer_id,h.id INTO tid,eid FROM inventory.transit_events h WHERE h.company_id=c AND h.id=NEW.event_id;END IF;
 SELECT * INTO ship FROM inventory.transit_transfers WHERE company_id=c AND id=tid;
 IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM platform.documents WHERE company_id=c AND id=tid AND document_type='TRANSIT_DISPATCH' AND state='POSTED') OR NOT EXISTS(SELECT 1 FROM inventory.transit_transfer_lines WHERE company_id=c AND transfer_id=tid) THEN RAISE EXCEPTION 'Transit shipment registry/lines mismatch' USING ERRCODE='23514';END IF;
 SELECT sum(cost) INTO total FROM inventory.transit_transfer_lines WHERE company_id=c AND transfer_id=tid;
 IF total>0 AND(ship.inventory_account_id IS NULL OR ship.transit_account_id IS NULL OR ship.journal_entry_id IS NULL OR ship.inventory_account_id=ship.transit_account_id) THEN RAISE EXCEPTION 'Transit shipment financial source missing' USING ERRCODE='23514';END IF;
 IF EXISTS(SELECT 1 FROM inventory.transit_line_balances WHERE company_id=c AND transfer_id=tid AND(remaining_quantity<0 OR remaining_cost<0 OR(remaining_quantity=0 AND remaining_cost<>0))) THEN RAISE EXCEPTION 'Transit source overdrawn or cost not fully cleared' USING ERRCODE='23514';END IF;
 IF EXISTS(SELECT 1 FROM inventory.transit_transfer_lines tl JOIN inventory.stock_balances b ON b.company_id=tl.company_id AND b.id=tl.stock_balance_id WHERE tl.company_id=c AND tl.transfer_id=tid AND(b.product_id<>tl.product_id OR b.warehouse_id<>ship.source_id)) THEN RAISE EXCEPTION 'Dispatch source stock mismatch' USING ERRCODE='23514';END IF;
 IF eid IS NOT NULL THEN
 SELECT * INTO ev FROM inventory.transit_events WHERE company_id=c AND id=eid;
 IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM platform.documents WHERE company_id=c AND id=eid AND state='POSTED' AND document_type=CASE WHEN ev.kind='RECEIPT' THEN 'TRANSIT_RECEIPT' ELSE 'TRANSIT_ADJUSTMENT' END) OR NOT EXISTS(SELECT 1 FROM inventory.transit_event_lines WHERE company_id=c AND event_id=eid) OR(ev.kind='RECEIPT' AND ev.warehouse_id<>ship.destination_id) OR(ev.kind='RETURN' AND ev.warehouse_id<>ship.source_id) THEN RAISE EXCEPTION 'Transit event state/warehouse mismatch' USING ERRCODE='23514';END IF;
 SELECT sum(cost) INTO total FROM inventory.transit_event_lines WHERE company_id=c AND event_id=eid;
 IF total>0 AND(ev.journal_entry_id IS NULL OR ev.debit_account_id IS NULL) THEN RAISE EXCEPTION 'Transit event journal missing' USING ERRCODE='23514';END IF;
 IF EXISTS(SELECT 1 FROM inventory.transit_event_lines el JOIN inventory.transit_transfer_lines tl ON tl.company_id=el.company_id AND tl.id=el.transfer_line_id LEFT JOIN inventory.stock_balances b ON b.company_id=el.company_id AND b.id=el.stock_balance_id WHERE el.company_id=c AND el.event_id=eid AND(tl.transfer_id<>tid OR(ev.kind='SHORTAGE')<>(el.stock_balance_id IS NULL) OR(el.stock_balance_id IS NOT NULL AND(b.product_id<>tl.product_id OR b.warehouse_id<>ev.warehouse_id)))) THEN RAISE EXCEPTION 'Transit event line/stock mismatch' USING ERRCODE='23514';END IF;
 IF ev.journal_entry_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM accounting.journal_entries je JOIN accounting.posting_batches pb ON pb.company_id=je.company_id AND pb.id=je.posting_batch_id WHERE je.company_id=c AND je.id=ev.journal_entry_id AND pb.source_document_id=eid AND pb.posting_kind='TRANSIT_'||ev.kind) THEN RAISE EXCEPTION 'Transit event journal source mismatch' USING ERRCODE='23514';END IF;
 END IF;
 IF ship.journal_entry_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM accounting.journal_entries je JOIN accounting.posting_batches pb ON pb.company_id=je.company_id AND pb.id=je.posting_batch_id WHERE je.company_id=c AND je.id=ship.journal_entry_id AND pb.source_document_id=tid AND pb.posting_kind='TRANSIT_DISPATCH') THEN RAISE EXCEPTION 'Transit dispatch journal source mismatch' USING ERRCODE='23514';END IF;RETURN NULL;
END $$;
DO $$ DECLARE tb text;BEGIN FOREACH tb IN ARRAY ARRAY['transit_transfers','transit_transfer_lines','transit_events','transit_event_lines'] LOOP EXECUTE format('CREATE CONSTRAINT TRIGGER transit_consistency AFTER INSERT ON inventory.%I DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION inventory.validate_transit()',tb);END LOOP;END $$;
REVOKE ALL ON FUNCTION identity.seed_transit_roles(uuid),inventory.transit_number(text),inventory.transit_delta(uuid,uuid,numeric,numeric),inventory.dispatch_transit(uuid,uuid,text,text,jsonb),inventory.post_transit_event(uuid,text,text,text,jsonb),inventory.guard_transit_document(),inventory.validate_transit() FROM PUBLIC;
GRANT SELECT ON inventory.transit_transfers,inventory.transit_transfer_lines,inventory.transit_events,inventory.transit_event_lines,inventory.transit_line_balances,inventory.transit_transfer_balances TO htt_app;
GRANT EXECUTE ON FUNCTION inventory.dispatch_transit(uuid,uuid,text,text,jsonb),inventory.post_transit_event(uuid,text,text,text,jsonb) TO htt_app;
